INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (1, 'for-what-its-worth', 'Úplný začátek. První lekce.', 'For What It''s Worth', NULL, 'BBz-Jyr23M4', 'Andy Guitar', 1, '20 minut', 'Dnes se něco naučíš. Dnes si něco zahraješ. Dva akordy a první písnička.', 1, 0, NULL, 1, 'published');
