INSERT INTO video_categories (video_id, category_id) VALUES (1, 2);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (2, 'kdyz-jsem-ja-slouzil', 'Český první večer', 'Když jsem já sloužil', NULL, 'ylS3SMfsa9g', 'Michaela Medek', 1, '20 minut', 'A a E. Nic víc. Příjemný český začátek, u kterého se nemusíš stydět, že začínáš.', 1, 0, NULL, 2, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (2, 1);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (3, 'three-little-birds', 'Tři akordy a úsměv', 'Three Little Birds', NULL, 'SV2ehlxGEFw', 'Andy Guitar', 2, '1 večer', 'E, A, D. Zní to jako písnička, ne jako cvičení. Přesně ten poměr náročnost / výsledek.', 0, 0, NULL, 3, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (3, 1);
INSERT INTO video_categories (video_id, category_id) VALUES (3, 2);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (4, 'bad-moon-rising', 'Groove, který sedí do ruky', 'Bad Moon Rising', NULL, 'ZUun3_932y0', 'Relax and Learn Guitar', 2, '1 večer', 'Tři otevřené akordy a basová nota. Zní to víc, než to je. Ideální po práci.', 0, 0, NULL, 4, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (4, 2);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (5, 'ring-of-fire', 'Jednoduchost a groove', 'Ring of Fire', 'Johnny Cash', 'FOhKXPTbt5k', 'Andy Guitar', 2, '1 večer', 'Proto má Johnny Cash vlastní sekci. Tři akordy a najednou hraješ něco, co zná každý.', 1, 1, NULL, 5, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (5, 4);
INSERT INTO video_categories (video_id, category_id) VALUES (5, 2);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (6, 'folsom-prison-blues', 'Až to chytneš, opravdu hraješ', 'Folsom Prison Blues', 'Johnny Cash', 'lFmVMOB8ycE', 'Andy Guitar', 3, '3 večery', 'Jedna z prvních skladeb, u které jsem měl pocit, že opravdu hraju. Není kam spěchat.', 0, 1, NULL, 6, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (6, 4);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (7, '5-pisni-na-3-akordy', 'Celý večer s Cashem', '5 písní na 3 akordy', NULL, 'fGuNJKurkNM', 'Andy Guitar', 2, '1 týden', 'Boy Named Sue, Ring of Fire, Folsom, Jackson. Vezmi kytaru a zůstaň u jednoho člověka.', 0, 0, NULL, 7, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (7, 4);
INSERT INTO video_categories (video_id, category_id) VALUES (7, 2);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (8, 'zakladni-vzory-prave-ruky', 'Fingerstyle pro normální lidi', 'Základní vzory pravé ruky', NULL, 'SRHVcZDWB3g', 'Relax and Learn Guitar', 2, '1 večer', 'Žádné extrémní techniky. Palec hraje bas, ostatní prsty zůstanou. Použitelné hned.', 0, 0, NULL, 8, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (8, 3);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (9, 'lasko-karel-kryl', 'Tady spousta lidí začíná', 'Lásko! — Karel Kryl', NULL, '46ZYT9hdYoQ', 'Michaela Medek', 3, '3 večery', 'Kryl má vlastní sekci, protože se k němu vracíme. Michaela to vysvětlí klidně a po česku.', 0, 1, NULL, 9, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (9, 5);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (10, 'sila-starejch-vin', 'Česká písnička, která sedí', 'Síla starejch vín', NULL, 'yK6YTr2PIj4', 'Michaela Medek', 2, '1 večer', 'Dobře vysvětlené, příjemný přístup. Přesně ten typ návodu, kvůli kterému tenhle web existuje.', 0, 0, NULL, 10, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (10, 2);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (11, 'november-rain-snadne-akordy', 'Zní mnohem složitěji, než je', 'November Rain — snadné akordy', NULL, 'YaBlUAnHQvY', 'Andy Guitar', 3, '3 večery', 'Zní mnohem složitěji, než ve skutečnosti je. Žádná sóla. Jen akordy a kousek melodie.', 0, 1, NULL, 11, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (11, 3);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (12, 'sovy-v-mazutu', 'Tohle zní jak kdyby to hrál přímo sám velký Franta Sahula!', 'Sovy v mazutu', NULL, 'Nr-AxIdT2k8', 'Kytary.cz', 1, '1 večer', 'Naprostá klasika, hrozně hezky to zní a chytnou se všichni.', 0, 0, NULL, 12, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (12, 1);
INSERT INTO video_categories (video_id, category_id) VALUES (12, 2);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (13, 'knockin-on-heavens-door', 'Klasika na pár akordů', 'Knockin'' on Heaven''s Door', NULL, 'dB7y6YM6RZw', 'Kytary.cz', 1, '1 večer', 'Česky nebo anglicky. Dylan, GnR nebo Tři sestry... je to jedno, zní to prostě nesmrtelně.', 0, 0, '2026-10-11T12:06:33', 13, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (13, 1);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (14, 'jasna-zprava', 'Do hospody i k táboráku', 'Jasná zpráva', NULL, 'BL1iIasJNKY', 'Kytary.cz', 1, '1 večer', 'Lehký rytmus a jedno z nejznámějších sól, které je velmi jednoduché.', 0, 0, '2026-10-11T12:15:36', 14, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (14, 1);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (15, 'slzy-tvy-mamy', 'Silná melodie', 'Slzy tvý mámy', NULL, 'msf7UL6VAXE', 'Kytary.cz', 3, '3 večery', 'Malinko těžší, už je tam barré akord a u vyhrávky složitější prstoklad, ale výsledek stojí za naučení. Zní to parádně.', 0, 0, '2026-10-11T12:18:57', 15, 'published');
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (16, 'muchomurky-bile', 'Ikonická melodie', 'Muchomůrky bílé', 'Garáž', 'WmYBMOmkjFg', 'Kytary.cz', 3, '3 večery', 'Akordy jsou celkem snadné, trochu cviku to chce s rytmem a přitlumováním. Zní to ale báječně. Jedna z mých nejoblíbenějších.', 0, 1, '2026-10-11T12:22:51', 16, 'published');
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (17, 'friday-im-in-love', 'Málo dřiny, velký výsledek', 'Friday I''m in Love', NULL, 'z09NgB59Vmk', 'The Stellar Guitarist', 2, '1 večer', 'Jednoduché akordy, krásné intro a ten song zní prostě dobře.', 0, 0, '2026-10-11T12:42:39', 17, 'published');
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (18, 'redemption-song', 'Bob Marley jen s kytarou', 'Redemption Song', NULL, 'R2y_nuoGpmg', 'Marty Music', 2, '1 večer', 'Bob Marley ji nahrál sám s akustickou kytarou, takže ti nic nechybí. Klidná písnička na večer.', 0, 1, '2026-10-20T23:32:18', 18, 'published');
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (19, 'take-me-home-country-roads', 'Country rytmus do ruky', 'Take Me Home, Country Roads', 'John Denver', 'UioPoWP2X_U', 'Relax and Learn Guitar', 2, '1 večer', 'Pár základních akordů a refrén, který každý zná. Ten rytmus pak použiješ i u dalších písniček.', 0, 0, '2026-10-20T23:33:55', 19, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (19, 1);
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (20, '4-pisne-na-akustiku', 'Čtyři klasiky v jednom videu', '4 písně na akustiku', NULL, '7FurwLN6Hmc', 'Relax and Learn Guitar', 2, '3 večery', 'Wish You Were Here, Imagine, The Joker a Tennessee Whiskey. Každá je jiná, ale všechny zvládneš s běžnými akordy. Na tři večery.', 0, 1, '2026-10-20T23:39:44', 20, 'published');
INSERT INTO videos (id, slug, title, song, artist, youtube_id, channel, difficulty, time, comment, featured, top, added, sort, status) VALUES (21, 'jolene', 'Nádherná melodie na tři akordy', 'Jolene', 'Dolly Parton', '_qpoL6_QZxk', 'Relax and Learn Guitar', 2, '1 večer', 'Dolly Parton zjednodušeně: tři akordy, jednoduchý rytmus a k tomu malý vybrnkávaný motiv, díky kterému to zní jako Jolene. Tip od návštěvníka webu.', 0, 0, '2026-10-24T12:00:00', 21, 'published');
INSERT INTO video_categories (video_id, category_id) VALUES (21, 2);
