INSERT INTO sections (id, title, text, filter, sort) VALUES (1, 'Začni dnes', 'Dnes se něco naučíš. Dnes si něco zahraješ.', 'start', 10);
INSERT INTO sections (id, title, text, filter, sort) VALUES (2, '3 akordy a hotovo', 'Tři akordy, a už to zní jako písnička. Nejmíň dřiny, nejvíc radosti.', 'three', 20);
INSERT INTO sections (id, title, text, filter, sort) VALUES (3, 'Fingerstyle, co se dá zvládnout', 'Vybrnkávání bez akrobacie. Věci, které opravdu použiješ.', 'fingerstyle', 30);
INSERT INTO sections (id, title, text, filter, sort) VALUES (4, 'Johnny Cash', 'Pár akordů a rytmus, který táhne. Na Cashovi se učí skvěle.', 'cash', 40);
INSERT INTO sections (id, title, text, filter, sort) VALUES (5, 'Karel Kryl', 'U Kryla začínala spousta z nás. Kytara a hlas, víc není potřeba.', 'kryl', 50);
INSERT INTO sections (id, title, text, filter, sort) VALUES (6, 'Top objevy', 'Pár videí, u kterých jsem si řekl: tohle musím ukázat dál.', 'top', 60);
INSERT INTO channels (id, name, url, text, sort) VALUES (1, 'Andy Guitar', 'https://www.youtube.com/@andyguitar', 'Ideální pro začátečníky. Klid, pořádek, písničky hned.', 10);
INSERT INTO channels (id, name, url, text, sort) VALUES (2, 'Relax and Learn Guitar', 'https://www.youtube.com/@relaxandlearnguitar', 'Nádherné fingerstyle aranže. Bez honění se za rychlostí.', 20);
INSERT INTO channels (id, name, url, text, sort) VALUES (3, 'Kytary.cz', 'https://www.youtube.com/@kytarycz', 'Český základ. Nástroje, rady, srozumitelný jazyk.', 30);
INSERT INTO channels (id, name, url, text, sort) VALUES (4, 'Michaela Medek', 'https://www.youtube.com/@michaelamedek', 'České návody a příjemný přístup. Kryl, písničky, klid.', 40);
